begin;
set local app.auvo_sync_write='true';
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public;
select plan(10);
select has_function('pcm','sso_informar_material_mediado',array['uuid','uuid','integer','text','jsonb'],'comando mediado existe');
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
values ('17994000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','s179-eventos@test.local',crypt('x',gen_salt('bf')),'{}','{}',now(),now());
insert into config.usuarios(user_id,papel,nome,ativo) values ('17994000-0000-4000-8000-000000000001','superadmin','Gestor sintético',true);
insert into pcm.clientes(id,nome,created_by) values ('17994000-0000-4000-8000-000000000002','Cliente A','17994000-0000-4000-8000-000000000001');
insert into config.sso_concessoes(usuario_id,acao,cliente_id) values ('17994000-0000-4000-8000-000000000001','material.gerir','17994000-0000-4000-8000-000000000002');
insert into pcm.ordens_servico(id,client_id,numero,titulo,categoria,created_by) values ('17994000-0000-4000-8000-000000000011','17994000-0000-4000-8000-000000000002','S179-EV-A','OS A','corretiva','17994000-0000-4000-8000-000000000001');
insert into pcm.listas_materiais(id,cliente_id,ordem_servico_id,responsavel,texto_original,criado_por) values ('17994000-0000-4000-8000-000000000021','17994000-0000-4000-8000-000000000002','17994000-0000-4000-8000-000000000011','cliente','Material A','17994000-0000-4000-8000-000000000001');
set local request.jwt.claims='{"sub":"17994000-0000-4000-8000-000000000001","role":"authenticated","user_role":"superadmin"}';
set local role authenticated;
select throws_ok($$select pcm.sso_informar_material_mediado('17994000-0000-4000-8000-000000000031','17994000-0000-4000-8000-000000000021',1,'disponibilidade','{"situacao":"informada_disponivel"}')$$,'55000','evento_material_bloqueado','gate fechado impede registro');
reset role;
update pcm.sso_eventos_materiais_mediados_gate set habilitado=true where id;
set local role authenticated;
select lives_ok($$select pcm.sso_informar_material_mediado('17994000-0000-4000-8000-000000000031','17994000-0000-4000-8000-000000000021',1,'disponibilidade','{"situacao":"informada_disponivel"}')$$,'disponibilidade informativa registrada');
select lives_ok($$select pcm.sso_informar_material_mediado('17994000-0000-4000-8000-000000000031','17994000-0000-4000-8000-000000000021',1,'disponibilidade','{"situacao":"informada_disponivel"}')$$,'replay idêntico aceito');
select lives_ok($$select pcm.sso_informar_material_mediado('17994000-0000-4000-8000-000000000032','17994000-0000-4000-8000-000000000021',2,'excecao','{"motivo":"faltante","descricao":"Material não encontrado"}')$$,'exceção reabre levantamento');
select throws_ok($$select pcm.sso_informar_material_mediado('17994000-0000-4000-8000-000000000033','17994000-0000-4000-8000-000000000021',1,'disponibilidade','{"situacao":"parcial"}')$$,'40001','revisao_obsoleta','revisão antiga recusada');
reset role;
select is((select count(*)::integer from pcm.sso_lista_materiais_eventos where lista_id='17994000-0000-4000-8000-000000000021'),2,'histórico preservado sem duplicata');
select is((select estado from pcm.listas_materiais where id='17994000-0000-4000-8000-000000000021'),'levantada','exceção retorna lista ao levantamento');
select is((select status from pcm.ordens_servico where id='17994000-0000-4000-8000-000000000011'),'solicitacao','evento não altera OS automaticamente');
select ok(has_function_privilege('authenticated','pcm.sso_informar_material_mediado(uuid,uuid,integer,text,jsonb)','execute') and not has_function_privilege('authenticated','pcm.sso_informar_material(uuid,uuid,integer,text,jsonb)','execute') and not has_function_privilege('anon','pcm.sso_informar_material_mediado(uuid,uuid,integer,text,jsonb)','execute'),'mediadora autenticada e núcleo privado');
select * from finish();
rollback;
